const btnSync = document.getElementById('btn-sync');
const tip = document.getElementById('ai4a11y-hover-tip');
const isEnabled = !!document.getElementById('ai4a11y-persistent-hover-styles');
if (!btnSync) return false;
if (!isEnabled) return true;

if (tip.getAttribute('role') !== 'tooltip') return false;
if (tip.getAttribute('aria-live') !== 'polite') return false;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

const tipStyle = window.getComputedStyle(tip);
const cr = contrast(tipStyle.color, tipStyle.backgroundColor);
if (cr === null || cr < 4.5) return false;

btnSync.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
if (tip.hidden) return false;
const bRect = btnSync.getBoundingClientRect();
const tRect = tip.getBoundingClientRect();

const overlapsVertically = (tRect.top < bRect.bottom && tRect.bottom > bRect.top);
const overlapsHorizontally = (tRect.left < bRect.right && tRect.right > bRect.left);
const obscures = overlapsVertically && overlapsHorizontally;
if (obscures) return false;

const initialTop = parseFloat(tip.style.top);
window.dispatchEvent(new Event('scroll'));
const scrolledTop = parseFloat(tip.style.top);
if (isNaN(scrolledTop)) return false;

document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
return true;

